// The ones that stay with you. Situations are composites; every dated fact is public record.
// Chains run on flags: a signature at thirty comes back at forty. Help lines are real.
import {rand} from './rand.js';
import {birthYearOf} from './thai-history.js';
import {regionAt} from './regions.js';
const O=(id,label,fx,outcome)=>({id,label,...fx,outcome});
const F=s=>({...s.pivotFlags,...s.story?.flags}),had=(k,gap)=>s=>typeof F(s)[k]==='number'&&s.age-F(s)[k]>=gap,cal=s=>{const y=birthYearOf(s);return y===null?null:y+s.age;};
const CITY=['khlong-toei','bang-na','sukhumvit','samut-prakan'],country=s=>!CITY.includes(regionAt(s,s.age-1)),male=s=>s.intake?.sex==='male',during=(a,b)=>s=>{const c=cal(s);return c!==null&&c+4>=a&&c<=b;};
const once=(id,p)=>s=>rand(s.seed,s.age,id)<p;
const scene=(id,category,min,max,tests,title,prompt,options,extra={})=>({id,category,min,max,director:true,...extra,eligible:s=>!!s.intake?.class&&tests.every(t=>t(s)),title,prompt,options});
const CHAIN=new Set(['g_bond','g_cell','g_home']);
export const HARD_ENCOUNTERS=[
 scene('g_sign','connection',20,40,[once('g_sign',.12)],'Sign here, it is only a form','{friend} has won a scholarship to study abroad. The office wants a guarantor, and {friend} has no one else. You have known each other since you shared a desk. It is one signature, and {friend} is crying with happiness.',[
  O('no','Say you cannot',{wellbeing:-5,skills:{eq:1}},'{friend} found someone else and did not invite you to the airport.'),
  O('sign','Sign',{wellbeing:4,flag:'g_signed'},'You signed without reading the fourth page. {friend} hugged you in the corridor. You kept the photograph.')],{rehearse:'If you are asked: read the penalty clause. Thai scholarship contracts commonly require the money back plus a penalty of up to twice as much, and a guarantor can be made to pay all of it.'}),
 scene('g_bond','money',30,60,[had('g_signed',10)],'The letter about {friend}','A registered letter. {friend} finished the doctorate, took a job overseas and never came back to serve the bond. The office wants the scholarship repaid three times over, and your name is the one in Thailand. The number you still have stopped answering years ago.',[
  O('court','Refuse and let them take you to court',{wellbeing:-18,skills:{iq:1},flag:'g_sued'},'You lost, slowly, over four years. They took it from your salary. {friend} posted photographs of a garden.'),
  O('instal','Pay it for the next twenty years',{cash:-60000,wellbeing:-14},'A slip every month. You came to know the clerk. You stopped telling the story, because people asked why you had signed.'),
  O('sell','Sell what you have and finish it',{cash:-200000,wellbeing:-10,skills:{drive:1}},'It was gone in a week. You found the photograph in a drawer and left it where it was.')]),
 scene('g_bus','work',20,20,[country,male,once('g_bus',.3),s=>birthYearOf(s)!==null&&birthYearOf(s)<=1970],'A man at the bus station','Your girl is expecting. There is nothing here after the harvest. A man in Mo Chit with good shoes knows a job that pays by the night; you only have to take a bag across town.',[
  O('home','Go home on the next bus',{wellbeing:-4},'You were poor where people knew your name.'),
  O('bag','Take the bag',{cash:3000,wellbeing:2,flag:'g_bag'},'It was heavier than it looked. He paid you. He asked you to do it again on Friday.')],{rehearse:'If a stranger pays too much for a small job: the job is the risk, and you are the person holding it.'}),
 scene('g_cell','health',25,25,[had('g_bag',5)],'Nobody was watching out for you','The bag was searched on the Friday. The man with good shoes had never heard of you. You had no lawyer, and you signed what they put in front of you because you read slowly. You run from something in the yard and fall from a wall. Nobody sets the leg. There are other things in that place you have never told anybody.',[
  O('quiet','Do what keeps you alive',{health:-24,wellbeing:-28,flag:'g_inside'},'Seven years. You stopped being called by your name in the second. The leg healed the way it wanted.'),
  O('write','Write to her and tell her not to wait',{health:-24,wellbeing:-22,skills:{eq:2},flag:'g_inside'},'She did not answer. You could not tell whether the letters left the building.')],{rehearse:'If you are arrested in Thailand: you may ask for a lawyer and for someone to be told. Do not sign what you cannot read. The Mental Health Hotline is 1323.'}),
 scene('g_home','family',35,35,[had('g_inside',10)],'The house you were going to build','You walk the last three kilometres because the bus costs money and the leg needs to learn. She is at the well with a child on her hip and four others around her. Their father left when the youngest came. She looks at the leg and then at your face and says your name as if she is checking it still works.',[
  O('stay','Stay, and carry water',{health:-4,wellbeing:2,skills:{eq:3}},'You were supposed to be her knight. You carry water. Neither of you has ever mentioned what either of you was supposed to be.'),
  O('leave','Say you were passing through',{wellbeing:-16},'You were on the road again before she had finished deciding what to say.')]),
 scene('i_condo','money',25,55,[during(1993,1996),once('i_condo',.5)],'The tower on the plan','A colleague has a deposit on a unit in a tower that does not exist yet. Prices have doubled in three years. Everyone at the office is in, and you can have the one next to his.',[
  O('no','Keep your money',{wellbeing:-2,later:[{after:5,wellbeing:4,text:'The tower stopped at the eleventh floor in 1997. Your colleague stopped coming to work.'}]},'He called you a coward at lunch and bought the other one as well.'),
  O('yes','Put down the deposit',{cash:-80000,wellbeing:3,later:[{after:5,wellbeing:-10,text:'The tower stopped at the eleventh floor in 1997. You still have the brochure and the debt.'}]},'You drove past the sign on Sundays.')],{rehearse:'This is real. Thai property lending collapsed in 1997 and unfinished towers stood empty for years.'}),
 scene('i_ptt','money',20,70,[during(2001,2001),once('i_ptt',.6)],'Shares in the oil company','The state oil company is selling shares to the public at thirty-five baht. Your brother-in-law says the government will never let it fail. Your mother says a bank has a roof.',[
  O('no','Leave it in the bank',{later:[{after:10,wellbeing:-4,text:'Your brother-in-law paid for his daughter’s degree with those shares. He has stopped mentioning it, which is worse.'}]},'The interest was small and arrived on time.'),
  O('yes','Buy what you can',{cash:-35000,later:[{after:10,cash:180000,wellbeing:4,text:'You sold the oil shares and paid off the house. You told people it was luck, and they agreed too quickly.'}]},'A piece of paper arrived, and you put it in the tin.')],{rehearse:'This is real. PTT sold shares to the public in late 2001 at 35 baht a share. Past results are no promise.'}),
 scene('i_shrimp','money',25,60,[during(2005,2011),once('i_shrimp',.5)],'Ponds on the family land','Your cousin in Chanthaburi cleared more in one crop of shrimp than your family has in ten years of rice. He will show you the ponds. The bank has a form for it.',[
  O('no','Keep the rice',{later:[{after:10,wellbeing:2,text:'The shrimp died in their ponds in a single season. Your rice was still rice.'}]},'Your cousin bought a pickup. You admired it.'),
  O('yes','Dig the ponds',{cash:-90000,wellbeing:3,later:[{after:5,cash:150000,text:'Two good crops. You paid back the bank and dug a third pond.'},{after:10,cash:-180000,wellbeing:-12,text:'In a single season the shrimp died in every pond on the coast. The ponds are still there, and nothing grows in that ground.'}]},'The first crop came in like money falling out of the water.')],{rehearse:'This is real. Early mortality syndrome swept Thai shrimp farms from about 2012 and output fell by around half within two years.'}),
 scene('i_rubber','money',25,60,[during(2008,2011),country,once('i_rubber',.6)],'Rubber at the highest price','Rubber has never been worth this much. The southern villages have new houses. Your neighbour cut down his fruit trees and planted, and tells you there is only one direction.',[
  O('no','Leave the fruit trees',{later:[{after:5,wellbeing:2,text:'Rubber was worth less than a bowl of noodles by then. You had mangoes.'}]},'Your neighbour stopped asking your opinion on anything.'),
  O('yes','Cut them down and plant',{cash:-50000,later:[{after:5,cash:-30000,wellbeing:-9,text:'The trees came into tapping just as the price fell away to almost nothing. Seven years of waiting bought you a sheet of rubber nobody wanted.'}]},'Saplings take seven years. You counted.')],{rehearse:'This is real. Natural rubber peaked in 2011 and had lost most of its price by 2016.'}),
 scene('i_land','money',25,55,[during(1990,1998),once('i_land',.5)],'A rice field by the planned line','A man from the district is selling a muddy plot on the edge of Bangkok. He says a train is coming on stilts. Nobody you know has ever seen a train on stilts.',[
  O('no','Say no',{later:[{after:20,wellbeing:-6,text:'You took the Skytrain past that plot. There is a tower on it with a gym on the roof. You got off a stop early.'}]},'You told it at dinner as a funny story about a salesman.'),
  O('yes','Buy the mud',{cash:-70000,later:[{after:20,cash:400000,wellbeing:5,text:'A developer paid you for the mud. You had forgotten where the deed was.'}]},'It flooded the first year. Your wife did not say anything, carefully.')],{rehearse:'This is real. Bangkok’s Skytrain opened in December 1999 and land beside its stations was remade.'}),
 scene('i_coin','money',20,60,[during(2017,2021),once('i_coin',.5)],'Your nephew’s coins','Your nephew shows you his phone. He has made a year of your salary since March. The exchange is registered here and pays you interest just for leaving it there.',[
  O('no','Say you do not understand it',{later:[{after:5,wellbeing:2,text:'Your nephew borrowed your motorbike to get to work.'}]},'He looked at you the way you once looked at your father.'),
  O('yes','Put your savings in',{cash:-100000,wellbeing:3,later:[{after:5,wellbeing:-12,text:'One morning the exchange stopped letting anyone take money out. You still get emails.'}]},'It went up. You checked it at red lights.')],{rehearse:'This is real. In July 2022 the exchange Zipmex froze customer withdrawals, including those of its Thai customers.'}),
 scene('g_empty','health',30,60,[once('g_empty',.08)],'Nothing is wrong','You have the job and the room and enough to eat. Nothing has happened. You have started standing on the footbridge on your way home, watching the traffic for longer than the traffic needs. Nobody in this city would notice for several days.',[
  O('ring','Ring someone, about nothing',{wellbeing:6,skills:{eq:2}},'You talked about the weather for nine minutes. It was the first time your voice had been used that day.'),
  O('temple','Go and sit somewhere people go to sit',{wellbeing:5},'Nobody asked you anything. An old woman moved her bag so you would have room.'),
  O('walk','Walk home and say nothing',{wellbeing:-12},'You were on time for work.')],{rehearse:'A city can do this: Durkheim called it anomie. If it is you, the Mental Health Hotline is 1323, and it answers at night.'}),
 scene('g_shell','family',25,70,[country,s=>['low_class','working_class'].includes(s.intake?.class),once('g_shell',.12)],'What the village keeps','The harvest failed. The rice bank is empty and there is no money for the ceremony. The whole village is going to do it anyway. You are asked to carry the thing that has always been carried, and everyone knows it will change nothing about the rain.',[
  O('carry','Carry it',{wellbeing:7,skills:{eq:1}},'Your shoulder hurt for a week. Nobody went hungry alone that year.'),
  O('no','Say it changes nothing',{wellbeing:-6,skills:{iq:1}},'You were right. You ate by yourself.')],{rehearse:'People with the least have always made the most of what is higher than themselves. Being poor has never stopped anyone asking why.'}),
 scene('g_joint','money',28,65,[s=>{const f=F(s);return f.married!==undefined&&f.separated===undefined;},once('g_joint',.15)],'The money you agreed about','You and {partner} have one rule about the account: nothing leaves it unless you have both said so. Your oldest friend is on the phone, needs it by Friday, swears on his children, and has asked you not to mention it at home.',[
  O('no','Say it is not only yours to give',{wellbeing:-3,skills:{eq:1}},'He said he understood. He has not rung since, and now you know what the friendship was made of.'),
  O('tell','Tell {partner}, and decide together',{wellbeing:2,skills:{eq:2}},'You said no together, at the kitchen table. Then you spent it on a course neither of you regretted.'),
  O('send','Send it and say nothing',{cash:-80000,wellbeing:-12,flag:'g_secret'},'He stopped answering in the second month. You have checked the account together every year since, and said nothing.')],{rehearse:'If people borrow from you: lend only what you have already said goodbye to. Decide the rule at home before the phone rings.'}),
 scene('g_margin','money',25,50,[s=>['working_class','middle_class'].includes(s.intake?.class),once('g_margin',.18)],'Your daughter does the sums','You drive to Bangkok for cloth, bring it home and sell it at two percent. You have one watch and one wallet. Your daughter has been to school and shows you on paper: if you count your own hours, the shop has never made a baht.',[
  O('same','Say the work is the point',{wellbeing:5,skills:{drive:1}},'You went on opening at six. Thirty years of two percent bought a piece of land in Bangkok, and you never told anyone what it cost.'),
  O('raise','Raise your prices and pay yourself',{cash:12000,wellbeing:-2,skills:{iq:1}},'You lost the customers who came for the price. You started to take Sundays off and did not know what to do with them.')]),
 scene('g_will','family',45,70,[s=>s.intake?.class!=='low_class',once('g_will',.14)],'What they left','Your parents never spent anything and it turns out they owned a piece of land. They left no will anyone can agree on. Your brother has already sold the car. Your sister has a lawyer. Everyone at the table was raised by the same two frugal people.',[
  O('give','Let them have it',{wellbeing:6,skills:{eq:3}},'You got a watch that did not work. You still have brothers and a sister, more or less, and you eat together at New Year.'),
  O('half','Insist on an even split, on paper',{cash:60000,wellbeing:-4,skills:{iq:1}},'It came out even. Nobody could say what was missing.'),
  O('court','Take it to court',{cash:90000,wellbeing:-16},'You won. At the next funeral you sat at different tables.')]),
 scene('g_gift','connection',25,55,[once('g_gift',.2)],'Credit at the shop','A family down the soi has been buying on credit for three years, and you know they will never clear it. Your son says you are being tricked. Their boy has just passed the exam and they have come to ask, without asking, about the fees.',[
  O('count','Show them the book',{cash:9000,wellbeing:-2,skills:{iq:1},later:[{after:15,wellbeing:-5,text:'The water came up and you moved your stock alone. They watched from the bridge, not unkindly.'}]},'They paid a little every month and stopped coming in.'),
  O('give','Pay the fees and lose the book',{cash:-15000,wellbeing:4,skills:{eq:2},flag:'g_gave',later:[{after:15,cash:30000,wellbeing:8,text:'The water came up in the night. People you had not asked carried your stock upstairs, and the boy, a doctor now, would not let you pay. Nobody mentioned it. That is how it works.'}]},'Your son said you were being tricked. You said yes.')],{rehearse:'In Thai this is บุญคุณ: a debt of gratitude that no ledger holds. Before banks and insurance, it was the insurance.'}),
 scene('g_half','money',45,45,[s=>s.finance&&s.finance.available+s.finance.reserve>=200000,once('g_half',.5)],'Past the halfway mark','You are forty-five. If you are lucky, you have used up half. You have been keeping money for a long time, for a day you can no longer describe.',[
  O('keep','Keep keeping it',{wellbeing:-3},'It grew. You looked at the number sometimes, as other people look at the sea.'),
  O('spend','Spend it on what you actually want, from people who make it well',{cash:-120000,wellbeing:9,skills:{eq:1}},'A good chair, from a man who cried a little when you paid him. A trip with your mother. He bought a better lathe.')])
].map(e=>CHAIN.has(e.id)?{...e,priority:-1,director:undefined}:e);
